import React, { createContext, useContext, useState } from 'react';

// 1. Create the Context
const ThemeContext = createContext('light');

export default function App() {
  const [theme, setTheme] = useState('light');

  return (
    // 2. Provide the Context to all children
    <ThemeContext.Provider value={theme}>
      <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>
        Toggle Theme
      </button>
      <MiddlemanComponent />
    </ThemeContext.Provider>
  );
}

// Notice this component doesn't take any props!
function MiddlemanComponent() {
  return (
    <div>
      <h2>I am the middleman. I don't care about the theme.</h2>
      <DeepChildComponent />
    </div>
  );
}

function DeepChildComponent() {
  // 3. Consume the Context directly where it's needed
  const theme = useContext(ThemeContext);

  return (
    <div style={{ 
      padding: '20px', 
      background: theme === 'dark' ? '#333' : '#FFF',
      color: theme === 'dark' ? '#FFF' : '#000'
    }}>
      Current Theme is: {theme}
    </div>
  );
}
